from pathlib import Path
import re,json,shutil,html
r=Path(__file__).resolve().parents[1];lib=r/'packages/blazor';dest=r/'docs/blazor';dest.mkdir(parents=True,exist_ok=True)
descriptions={
'FlowHC':'Horizontal layout with wrapping, alignment and spacing.','FlowVC':'Vertical layout with spacing and alignment.','FlowCard':'A content surface with header, body and footer slots.','FlowDivider':'A labelled horizontal or vertical separator.','FlowLabel':'Accessible labels with an optional required indicator.','FlowImage':'Images with alternative text and a fallback source.','FlowBadge':'Compact semantic labels and status indicators.','FlowLoader':'Accessible loading feedback.','FlowButton':'Typed variants, semantic colors and loading states.','FlowThemeProvider':'Scoped light, dark and system palettes with runtime customization.',
'FlowInput':'Text entry with optional EditForm validation.','FlowPasswordInput':'Password entry with an accessible reveal button.','FlowTextArea':'Multiline input with resize, autogrow and character counts.','FlowNumberInput':'Typed numeric input with nullable values, bounds and steppers.','FlowCheckbox':'Boolean input with a separate indeterminate state.','FlowSwitch':'A native boolean switch with a stable label.',
'FlowDropdown':'Searchable single selection with an in-field clear action.','FlowMultiSelect':'Multiple selection with removable chips inside the field.','FlowRadioGroup':'Native radio choices with optional rich content.',
'FlowDialog':'Modal content with focus confinement, close policies and footer slots.','FlowDrawer':'A modal side panel using the same close and focus behavior as Dialog.','FlowPopover':'Anchored click-triggered content with outside dismissal.','FlowTooltip':'Short noninteractive hints on hover or keyboard focus.','FlowToast':'Transient messages with close and configurable automatic dismissal.',
'FlowTabs':'Keyboard-accessible tabs with keyed content.','FlowBreadcrumbs':'A navigation trail with a marked current page.','FlowPagination':'Bound page selection with a bounded page-number window.',
'FlowAccordion':'Expandable keyed sections in single or multiple-open mode.','FlowTable':'Typed columns, cell templates, local sorting and paging.','FlowTree':'Single selection, controlled expansion and keyboard navigation for hierarchical data.'}
base=(lib/'Styling/FlowComponentBase.cs').read_text();field=(lib/'Styling/FlowFieldBase.cs').read_text();textbase=(lib/'Styling/FlowTextFieldBase.cs').read_text();popup=(lib/'Styling/FlowPopupFieldBase.cs').read_text();selection=(lib/'Styling/FlowSelectionFieldBase.cs').read_text();modal=(lib/'Styling/FlowModalBase.cs').read_text()
controls=[]
for category in ['Foundation','Forms','Selection','Overlays','Navigation','DataDisplay']:
 for file in sorted((lib/category).rglob('*.razor')):
  name=file.stem;source=file.with_suffix('.razor.cs').read_text();sources=base+'\n'+source
  if category=='Forms':sources+='\n'+field+ ('\n'+textbase if name in ['FlowInput','FlowPasswordInput','FlowTextArea'] else '')
  if category=='Selection':sources+='\n'+field+'\n'+(selection if name=='FlowRadioGroup' else popup)
  if name in ['FlowDialog','FlowDrawer']:sources+='\n'+modal
  parameters=[];seen=set()
  for match in re.finditer(r'\[Parameter(?:\([^\]]*\))?(?:,[^\]]*)?\]\s+public\s+(.+?)\s+(\w+)\s*\{\s*get;',sources):
   kind,key=match.groups()
   if key not in seen:parameters.append({'name':key,'type':kind});seen.add(key)
  examples=[]
  for demo in (r/'examples/blazor/Components/Demos').glob('*Demo.razor'):
   for match in re.finditer(r'<DemoBlock[^>]*>(.*?)</DemoBlock>',demo.read_text(),re.S):
    if '<'+name in match[1]:
     c=demo.with_suffix('.razor.cs').read_text();m=re.search(r'private const string (?:ExampleCode|LoginCode) = """\n(.*?)\n        """;',c,re.S)
     code='\n'.join(line[8:] if line.startswith(' '*8) else line for line in m[1].splitlines()) if m else ''
     examples.append({'markup':match[1].strip(),'code':code})
  if not examples:
   home=(r/'examples/blazor/Components/Pages/Home.razor.cs').read_text();constant='LayoutCode' if name in ['FlowHC','FlowVC','FlowCard','FlowDivider'] else 'PresentationCode' if name in ['FlowLabel','FlowImage','FlowBadge','FlowLoader'] else 'ButtonCode' if name=='FlowButton' else 'ThemeCode'
   m=re.search('private const string '+constant+r' = """\n(.*?)\n        """;',home,re.S)
   if m:examples=[{'markup':'\n'.join(line[8:] if line.startswith(' '*8) else line for line in m[1].splitlines()),'code':''}]
  controls.append({'name':name,'category':category,'description':descriptions[name],'namespace':'FlowUI.Blazor.'+category if category!='Foundation' else 'FlowUI.Blazor.'+('Layout' if name in ['FlowHC','FlowVC','FlowCard','FlowDivider'] else 'Buttons' if name=='FlowButton' else 'Theming' if name=='FlowThemeProvider' else 'Presentation'),'parameters':parameters,'examples':examples,'sourcePath':str(file.relative_to(r))})
assert len(controls)==30
(dest/'docs.json').write_text(json.dumps({'version':'0.3.0','published':False,'controls':controls},indent=2))
(dest/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FlowUI Blazor documentation</title><meta name="description" content="Setup, usage and parameter reference for 30 FlowUI Blazor controls."><link rel="stylesheet" href="theme.css"><script src="app.js" defer></script></head><body><aside><a class="brand" href="#start"><span>F</span><div>FlowUI<small>BLAZOR DOCS</small></div></a><label class="search-label" for="search">Find a control</label><input id="search" type="search" placeholder="Search components…"><nav id="navigation" aria-label="Documentation"></nav><div class="sidebar-foot">.NET 10 · v0.3.0 preview</div></aside><main><header><span class="eyebrow">DESIGN SYSTEM / C#</span><button id="appearance" type="button">Switch appearance</button></header><article id="content"><h1>Loading documentation…</h1></article></main></body></html>''')
(dest/'theme.css').write_text('''*{box-sizing:border-box}body{margin:0;font:15px/1.65 system-ui,sans-serif;color:#172033;background:#f7f9fc;display:grid;grid-template-columns:265px minmax(0,1fr);--surface:#fff;--border:#dfe5ef;--muted:#66758d;--primary:#2563eb}body.dark{color:#edf2fb;background:#101827;--surface:#192438;--border:#33415a;--muted:#a3b1c8;--primary:#93b5ff}aside{position:sticky;top:0;height:100vh;overflow:auto;background:var(--surface);border-right:1px solid var(--border);padding:28px 18px}.brand{display:flex;gap:12px;align-items:center;color:inherit;text-decoration:none;font-weight:800;font-size:23px;margin-bottom:30px}.brand>span{display:grid;place-items:center;width:42px;height:42px;background:#2563eb;color:#fff;border-radius:11px}small{display:block;font-size:9px;letter-spacing:2px;color:var(--muted)}input{width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:7px;background:var(--surface);color:inherit}.search-label{display:block;font-size:12px;margin-bottom:6px;font-weight:600}nav h2{font-size:10px;text-transform:uppercase;letter-spacing:1.5px;color:var(--muted);margin:24px 8px 6px}nav a{display:block;padding:7px 10px;color:var(--muted);text-decoration:none;border-radius:6px;font-size:13px}nav a:hover,nav a.active{background:color-mix(in srgb,var(--primary) 10%,transparent);color:var(--primary)}main{padding:32px clamp(20px,5vw,72px);min-width:0;max-width:1250px}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border);padding-bottom:24px;margin-bottom:35px;gap:1rem}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:var(--primary)}button{font:inherit;font-size:12px;color:inherit;border:1px solid var(--border);border-radius:7px;background:var(--surface);padding:8px 12px;cursor:pointer}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;letter-spacing:-1.5px;margin:0 0 16px}h2{margin-top:32px;font-size:20px}h3{font-size:15px}p{max-width:800px;color:var(--muted)}.pill{display:inline-block;padding:3px 10px;background:color-mix(in srgb,var(--primary) 10%,transparent);color:var(--primary);font-size:11px;border-radius:20px;margin-bottom:18px}.note{padding:16px 20px;background:var(--surface);border:1px solid var(--border);border-radius:10px;color:var(--muted);font-size:13px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card{display:block;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px;color:inherit;text-decoration:none}.card h3{margin:0 0 5px}.card p{font-size:13px;margin:0}pre{position:relative;overflow:auto;padding:20px;border:1px solid var(--border);border-radius:10px;background:var(--surface);font-size:12px;line-height:1.65;max-width:100%}code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.code-head{display:flex;justify-content:space-between;align-items:center;margin-top:20px;font-size:12px;color:var(--muted)}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px;background:var(--surface)}th,td{padding:12px;text-align:left;border:1px solid var(--border)}th{font-weight:600}td code{font-size:12px}a{color:var(--primary)}.sidebar-foot{padding:25px 10px;color:var(--muted);font-size:11px}li{margin:8px 0}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--primary);outline-offset:3px}@media(max-width:760px){body{display:block}aside{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--border);padding:16px}nav{max-height:220px;overflow:auto}.brand{margin-bottom:16px}.sidebar-foot{display:none}main{padding:24px 16px}.cards{grid-template-columns:1fr}}''')
(dest/'app.js').write_text(r'''
let data;const content=document.querySelector('#content'),navigation=document.querySelector('#navigation');
const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function code(text,label){return '<div class="code-head"><span>'+label+'</span><button type="button" class="copy">Copy</button></div><pre><code>'+esc(text)+'</code></pre>';}
const setup=`dotnet add package FlowUI.Blazor --version 0.3.0`;
const imports=`@using FlowUI.Blazor.Layout\n@using FlowUI.Blazor.Presentation\n@using FlowUI.Blazor.Buttons\n@using FlowUI.Blazor.Theming\n@using FlowUI.Blazor.Forms\n@using FlowUI.Blazor.Selection\n@using FlowUI.Blazor.Overlays\n@using FlowUI.Blazor.Navigation\n@using FlowUI.Blazor.DataDisplay\n@using FlowUI.Blazor.Styling`.replace(/\\n/g,'\n');
function nav(){const query=document.querySelector('#search').value.toLowerCase();navigation.innerHTML='<a href="#start">Getting started</a><a href="#release">Publishing and hosting</a>'+[...new Set(data.controls.map(c=>c.category))].map(group=>'<h2>'+esc(group)+'</h2>'+data.controls.filter(c=>c.category===group&&c.name.toLowerCase().includes(query)).map(c=>'<a href="#'+c.name+'"'+(location.hash==='#'+c.name?' class="active"':'')+'>'+c.name+'</a>').join('')).join('');}
function render(){const key=location.hash.slice(1)||'start';nav();if(key==='start'){content.innerHTML='<span class="pill">30 controls · .NET 10</span><h1>Build with FlowUI.<br>Stay in C#.</h1><p>A Blazor component library with separated Razor templates, code-behind and isolated CSS. Browse real usage code and parameter references for each control.</p><div class="note">Version 0.3.0 is prepared for release. NuGet publication is pending; the install command below applies after publication. This site is documentation. The interactive Blazor gallery is included in the source project.</div><h2>Install and import</h2>'+code(setup,'After NuGet publication')+code(imports,'_Imports.razor')+'<h2>Enable interaction and styles</h2><p>Reference the library from an interactive Blazor host. The included sample uses Interactive Server; the library does not set a render mode. Link your host’s generated <code>MyApp.styles.css</code>, which imports the library’s isolated CSS. No script tag is required for FlowUI’s dynamically imported helpers.</p>'+code('<FlowThemeProvider Mode="FlowThemeMode.System">\n    <FlowButton OnClick="SaveAsync">Save</FlowButton>\n</FlowThemeProvider>','Razor')+'<h2>Explore components</h2><div class="cards">'+[...new Set(data.controls.map(c=>c.category))].map(group=>'<a class="card" href="#'+data.controls.find(c=>c.category===group).name+'"><h3>'+esc(group)+'</h3><p>'+data.controls.filter(c=>c.category===group).length+' controls</p></a>').join('')+'</div>';}else if(key==='release'){content.innerHTML='<span class="pill">Release guide</span><h1>Publish the library.</h1><p>The package and documentation have separate release paths. Your NuGet account owns the package; this static reference can be hosted independently of the Blazor gallery.</p><h2>Pack and publish</h2>'+code('dotnet build FlowUI.Blazor.slnx -c Release\ndotnet pack packages/blazor/FlowUI.Blazor.csproj -c Release -o artifacts/blazor\ndotnet nuget push artifacts/blazor/FlowUI.Blazor.0.3.0.nupkg --source https://api.nuget.org/v3/index.json --api-key "$NUGET_API_KEY"','Shell')+'<p>Create a NuGet API key scoped to FlowUI.Blazor and add it to the repository secret named NUGET_API_KEY. The included workflow can then be started manually from GitHub Actions. Choose and add your intended license before the public release. Check package-ID ownership and increment Version for each release.</p><h2>Host the gallery</h2><p>The sample uses Interactive Server and requires ASP.NET Core hosting with a persistent server connection. It cannot be served as static HTML. A Dockerfile is included to deploy it on a .NET 10-capable host. Static documentation is in docs/blazor and can also be hosted on GitHub Pages.</p><a href="https://learn.microsoft.com/en-us/nuget/quickstart/create-and-publish-a-package-using-the-dotnet-cli">Official NuGet publishing guide</a>';}else{const c=data.controls.find(c=>c.name===key);if(!c){content.innerHTML='<h1>Control not found</h1><a href="#start">Getting started</a>';return;}content.innerHTML='<span class="pill">'+esc(c.category)+'</span><h1>'+c.name+'</h1><p>'+esc(c.description)+'</p>'+code('@using '+c.namespace,'Namespace')+'<h2>Usage</h2>'+c.examples.map(e=>code(e.markup,'Razor')+(e.code?'<details><summary>Complete example code-behind</summary>'+code(e.code,'C#')+'</details>':'')).join('')+'<h2>Parameters</h2><p>Parameters below include inherited style and field parameters. Model validation remains your application’s responsibility.</p><div class="table-scroll"><table><thead><tr><th>Parameter</th><th>Type</th></tr></thead><tbody>'+c.parameters.map(p=>'<tr><td><code>'+esc(p.name)+'</code></td><td><code>'+esc(p.type)+'</code></td></tr>').join('')+'</tbody></table></div><h2>Source</h2><p><code>'+esc(c.sourcePath)+'</code></p>';if(c.name==='FlowTable'||c.name==='FlowTree')content.innerHTML+='<div class="note">This preview uses in-memory data. Server-side querying, virtualization, drag-and-drop, and multi-selection are not provided by these controls.</div>';}
content.querySelectorAll('.copy').forEach(button=>button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(button.parentElement.nextElementSibling.textContent);button.textContent='Copied';}catch{button.textContent='Select code to copy';}}));}
window.addEventListener('hashchange',()=>{render();scrollTo(0,0)});document.querySelector('#search').addEventListener('input',nav);document.querySelector('#appearance').addEventListener('click',()=>document.body.classList.toggle('dark'));
fetch('docs.json').then(r=>{if(!r.ok)throw new Error('Docs unavailable');return r.json()}).then(result=>{data=result;render()}).catch(()=>{content.innerHTML='<h1>Documentation could not load.</h1><p>Refresh the page to try again.</p>'});
''')
app=dest/'app.js';app.write_text(app.read_text().replace(r'\\n',r'\n'))
print({'controls':len(controls),'docs':str(dest),'parameter_count':sum(len(c['parameters']) for c in controls)})
